<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/LinkChecker.php';require_once __DIR__.'/../core/Json.php';use Core\CacheStore;use Core\LinkChecker;$quiet=false;foreach(array_slice(isset($argv)?$argv:array(),1)as $a){if($a==='--quiet'||$a==='-q'){$quiet=true;}}$start=time();$log=array('action'=>'link_check_minutely','version'=>ML_APP_VERSION,'started_at'=>date('Y-m-d H:i:s'),);try{$rows=CacheStore::itemsWithLinks(1);if(!$rows){$log['status']='empty';$log['message']='没有带下载链接的条目，无需检测';}else{$row=$rows[0];$raw=(string)$row['download_url'];$links=array();if(strpos($raw,'[')===0){$arr=json_decode($raw,true);if(is_array($arr)){foreach($arr as $e){if(is_array($e)&&!empty($e['url'])){$links[]=array('label'=>(isset($e['label'])?(string)$e['label']:'下载'),'url'=>(string)$e['url']);}elseif(is_string($e)&&$e!==''){$links[]=array('label'=>'下载','url'=>$e);}}}}else{foreach(preg_split('/\r?\n/',$raw)as $u){$u=trim((string)$u);if($u!==''){$links[]=array('label'=>'下载','url'=>$u);}}}if(!$links){$log['item_id']=(int)$row['id'];$log['status']='no_links';$log['message']='条目有 download_url 但解析不出有效链接（已写哨兵记录跳过）';try{CacheStore::saveLinkChecks((int)$row['id'],array(array('label'=>'下载','url'=>mb_substr($raw,0,2048),'ok'=>false,'code'=>0,'msg'=>'无有效链接(已跳过)',)));}catch(\Throwable $ex){$log['save_error']=$ex->getMessage();}}else{$results=array();$ok=0;$dead=0;foreach($links as $l){$url=trim((string)$l['url']);if($url===''){continue;}$r=LinkChecker::check($url);$results[]=array('label'=>(string)$l['label'],'url'=>$url,'ok'=>(bool)$r['ok'],'code'=>(int)$r['code'],'msg'=>(string)$r['msg'],);if(!empty($r['ok'])){$ok++;}else{$dead++;}}try{CacheStore::saveLinkChecks((int)$row['id'],$results);$log['item_id']=(int)$row['id'];$log['links_total']=count($results);$log['ok']=$ok;$log['dead']=$dead;$log['status']='done';}catch(\Throwable $ex){$log['item_id']=(int)$row['id'];$log['status']='save_failed';$log['message']=$ex->getMessage();}}}}catch(\Throwable $e){$log['status']='error';$log['message']=$e->getMessage();error_log('[link_check_minutely] '.$e->getMessage());}$log['elapsed_ms']=(int)round((microtime(true)-$start)*1000);$log['finished_at']=date('Y-m-d H:i:s');try{CacheStore::writeSyncLog('cron:link_check_minutely',array($log),(int)($log['ok']??0));}catch(\Throwable $e){error_log('[link_check_minutely] write log failed: '.$e->getMessage());}if(!$quiet){echo json_encode($log,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n";}